    "question": "A社は、B社にソフトウェアの開発を委託し、それを稼働させるためのサーバとクライアントPCを購入したところ、目的物となる納品物が、契約内容に適合しない事実を知った。民法の契約不適合責任に関する記述として、適切なものはどれか。ただし、A社とB社の間で契約不適合責任に関する特約は合意されていないものとする。",
