      "イ": "A社には、契約不適合の程度に応じた目的物の修補、代替物又は不足分の引渡し、損害賠償、契約の解除、及び履行の追完請求を行ったが履行の追完がなされない場合における代金の減額を求める権利がある。",
      "ウ": "A社は、目的物の修補、代替物又は不足分の引渡しの請求を行う場合、成果物の引渡しから1年以内に請求をしなければならない。",
