    "category": "システム開発・運用・IT基盤",
    "question": "JIS X 0153:2015（利用者用文書類の設計者及び作成者のための要求事項）によれば、システム及びソフトウェアの利用者用文書類の利用モードには“教習モード”及び“参照モード”がある。“参照モード”の利用者用文書に対する要求事項として適切なものはどれか。\n［教習モード］ソフトウェアの利用経験のない人が作業を遂行できるようにするために、作業を実行するときにソフトウェアの使用法を教える利用モード\n［参照モード］ソフトウェアの機能に慣れている利用者のために、選択した要素の全ての事実を含み、特定の情報への迅速なアクセスを提供する利用モード",
