    "explanation": "システムの運用管理では、障害や故障等によるデータ消失に備えて、バックアップを取り、復旧するための対策が取られていることが留意点となり、ウが適切。アは開発手法の適用、エは新規導入時のデータ移行で、いずれもシステムの開発・保守に関する留意点である。イはシステムへのアクセス管理（アクセス管理等の方針）で、IT全般統制の中の別の区分（システムの安全性の確保）の留意点である。"
