      "ウ": "自己と関係する個人データを基に、プロファイリングなどの自動化された取扱いだけに基づいて行われた、法的効果をもたらす決定に服しない権利",
      "エ": "ダイレクトマーケティングを目的とした個人データの取扱いに異議を唱えることによって、自己と関係する個人データを当該目的で取り扱わせないようにする権利"
