      "ウ": "経営判断に関与することを避けるため、不備を改善する際の経済合理性などの判断は行わず、経営者に対する改善勧告とする。",
      "エ": "将来のフォローアップに際して、客観的で中立的な判断を阻害する要因となるので、改善勧告の優先度付けを行うことを避ける。"
