    "explanation": "FTPは、サーバへの接続時にユーザ名とパスワードによるログイン処理が必要（匿名FTPではユーザ名にanonymousなどを使用）なのに対し、HTTPは通常ログイン処理なしで利用できるため、アが適切。イはHTTPでもPOSTやPUTメソッドでアップロードができる。ウはHTTPでもバイナリファイル（画像・実行ファイルなど）を転送できる。エはFTPも異なるOS間でファイル転送が可能で、同一OS間に限られない。"
