    "choices": {
      "ア": "削除する機能が用意されていないエンティティがあるので、誤登録や多重登録したエンティティを削除できないおそれがある。",
      "イ": "どの機能からも参照されないエンティティがあるので、必要な機能が漏れているおそれがある。",
      "ウ": "複数の機能が同一のエンティティを更新するので、デッドロックが発生するおそれがある。",
      "エ": "複数の機能から生成されるエンティティがあるので、機能が重複しているおそれがある。"
    },
    "answer": "ア",
