    "explanation": "生産者危険は、合格とすべき（良い）ロットを、抜取検査で誤って不合格と判定してしまう確率であり、ウが正しい。消費者危険（イ）は、不合格とすべき（悪い）ロットを誤って合格としてしまう確率である。アの合格品質水準（AQL）は合格とみなす品質の水準、エの有意水準は統計的検定で帰無仮説を棄却する基準となる確率であり、設問の確率とは異なる。"
