    "question": "前期の製品Aの売上高は1,000万円、営業利益は50万円であり、限界利益は400万円であった。当期は売上高が10%減少することが予想されている。当期も前期と同じ営業利益を得るために必要な、固定費の削減額は何万円か。ここで、当期の限界利益率は前期と同じものとする。",
