      "イ": "抽出されるサンプル数は、統計的サンプリングと非統計的サンプリングの選択を決定付ける重要な判断基準である。",
      "ウ": "抽出するサンプルを統計的に決定する手法ではなく、サンプルに対して評価手続を実施した結果を統計的に推定する方法である。",
