    "question": "（1）～（4）はある障害の発生から本格的な対応までの一連の活動である。（1）～（4）の各活動とそれに対応するITILの管理プロセスの組合せのうち、適切なものはどれか。\n（1）利用者からサービスデスクに“特定の入力操作が拒否される”という連絡があったので、別の入力操作による回避方法を利用者に伝えた。\n（2）原因を開発チームで追究した結果、アプリケーションプログラムに不具合があることが分かった。\n（3）障害の原因となったアプリケーションプログラムの不具合を改修する必要があるのかどうか、改修した場合に不具合箇所以外に影響が出る心配はないかどうかについて、関係者を集めて確認し、改修することを決定した。\n（4）改修したアプリケーションプログラムの稼働環境への適用については、利用者への周知、適用手順及び失敗時の切戻し手順の確認など、十分に事前準備を行った。",
    "choices": {
      "ア": "（1）インシデント管理／（2）問題管理／（3）変更管理／（4）リリース管理及び展開管理",
      "イ": "（1）インシデント管理／（2）問題管理／（3）リリース管理及び展開管理／（4）変更管理",
      "ウ": "（1）問題管理／（2）インシデント管理／（3）変更管理／（4）リリース管理及び展開管理",
      "エ": "（1）問題管理／（2）インシデント管理／（3）リリース管理及び展開管理／（4）変更管理"
    },
    "answer": "ア",
    "explanation": "（1）は、利用者からの連絡に対して回避方法を伝えて、サービスを早く回復させる活動でインシデント管理。（2）は、原因を追究して不具合を特定する活動で問題管理。（3）は、改修の要否や影響範囲を関係者で確認して決定する活動で変更管理（変更の評価・承認）。（4）は、改修したプログラムを稼働環境へ適用するための準備（周知、適用手順、切戻し手順の確認）の活動で、リリース管理及び展開管理である。したがってアが正しい。イ・エは（3）と（4）が入れ替わっており、ウ・エは（1）と（2）が入れ替わっている。"
